def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    Converts a :class:`datetime.timedelta` instance into a JSON‑serialisable
    representation.  The function returns ``None`` if *value* is ``None``;
    otherwise it returns the total number of seconds represented by the
    timedelta as a float.

    :param value: a :class:`datetime.timedelta` instance or ``None``
    :type value: datetime.timedelta or None
    :return: total seconds as float or ``None``
    """
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError(f"Expected a time object, got {type(value).__name__}")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None

    # Handle shapely-like Point objects
    if hasattr(value, "geom_type") and getattr(value, "geom_type", None) == "Point":
        return {"x": value.x, "y": value.y, "z": getattr(value, "z", None)}

    # Handle dict-like objects with x, y (and optional z)
    if isinstance(value, dict):
        if "x" in value and "y" in value:
            return {"x": value["x"], "y": value["y"], "z": value.get("z")}

    # Handle objects with x and y attributes
    if hasattr(value, "x") and hasattr(value, "y"):
        return {"x": getattr(value, "x"), "y": getattr(value, "y"), "z": getattr(value, "z", None)}

    # Handle iterable (tuple, list, numpy array, etc.)
    try:
        coords = list(value)
        if len(coords) >= 2:
            return {"x": coords[0], "y": coords[1], "z": coords[2] if len(coords) > 2 else None}
    except TypeError:
        pass

    # Fallback: return the value unchanged
    return value

def keys(self):
    """Return the keys of the record."""
    return list(self._data.keys())

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(session, *args, **kwargs):
            tx = session.begin_transaction(timeout=timeout, metadata=metadata)
            try:
                result = func(tx, *args, **kwargs)
                tx.commit()
                return result
            except Exception:
                tx.rollback()
                raise
        return wrapper
    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Assume the container holds its elements in a list-like attribute named `data`.
    if not hasattr(self, "data"):
        raise AttributeError("The object does not have a 'data' attribute.")
    try:
        return self.data.index(key)
    except ValueError:
        raise ValueError(f"{key!r} is not present in the container.")

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys are supplied, return all items
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            result[self._keys[key]] = self._values[key]
        else:
            # Handle string (or other) keys
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def round_half_to_even(n):
    """
    Round a number to the nearest integer using the round-half-to-even rule.
    This is the same as Python's built-in round function, but returns an int.
    """
    return int(round(n))

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    def __init__(self, *args, **kwargs):
        # Initialize the base Point with any positional arguments
        super(self.__class__, self).__init__(*args)
        # Set attributes for each field, defaulting to None if not provided
        for field in fields:
            setattr(self, field, kwargs.get(field, None))
    def __repr__(self):
        field_str = ', '.join(f'{k}={getattr(self, k)!r}' for k in fields)
        return f'{name}({field_str})'
    # Prepare class attributes
    attrs = {
        '__init__': __init__,
        '__repr__': __repr__,
        'fields': fields,
        'srid_map': srid_map,
        '__annotations__': {k: v for k, v in fields.items()}
    }
    # Dynamically create and return the new subclass of Point
    return type(name, (Point,), attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            print(f"DeprecationWarning: {message}")
            return func(*args, **kwargs)
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = []
    num = ''
    for ch in s:
        if ch.isdigit():
            num += ch
        else:
            if num:
                parts.append(int(num))
                num = ''
    if num:
        parts.append(int(num))
    return tuple(parts)

def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
            finally:
                if lock:
                    lock.release()
            result = func(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                cache[k] = result
            finally:
                if lock:
                    lock.release()
            return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and maxsize <= 0:
        raise ValueError("maxsize must be a positive integer or None")
    def decorating_function(user_function):
        cache = {}
        def make_key(args, kwargs):
            if typed:
                key = args + tuple(type(a) for a in args)
                kw = tuple(sorted((k, type(v)) for k, v in kwargs.items()))
            else:
                key = args
                kw = tuple(sorted(kwargs.items()))
            return key + kw
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move to end to mark as recently used
                result = cache.pop(key)
                cache[key] = result
                return result
            result = user_function(*args, **kwargs)
            cache[key] = result
            if maxsize is not None and len(cache) > maxsize:
                # Pop the first item (least recently used)
                cache.pop(next(iter(cache)))
            return result
        return wrapper
    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    from functools import wraps

    def decorator(func):
        cache = {}
        freq = {}
        if maxsize <= 0:
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key = (key, tuple(type(arg) for arg in args),
                       tuple((k, type(v)) for k, v in kwargs.items()))
            if key in cache:
                freq[key] += 1
                return cache[key]
            # Compute result
            result = func(*args, **kwargs)
            # Add to cache
            cache[key] = result
            freq[key] = 1
            # Evict if necessary
            if len(cache) > maxsize:
                # Find key with minimum frequency
                min_freq = min(freq.values())
                # Collect keys with min_freq
                candidates = [k for k, f in freq.items() if f == min_freq]
                # Evict one of them (first)
                evict_key = candidates[0]
                del cache[evict_key]
                del freq[evict_key]
            return result

        return wrapper

    return decorator

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(func, *args, **kwargs)
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with truncated file paths and limited stack depth.
    """
    import traceback
    import os

    def _format_traceback(tb, level=0):
        if tb is None or level >= max_level:
            return ""
        frames = traceback.extract_tb(tb)
        lines = []
        for frame in frames:
            # Truncate file path
            path_parts = frame.filename.split(os.sep)
            if len(path_parts) > max_path_level:
                truncated = os.sep.join(["..."] + path_parts[-max_path_level:])
            else:
                truncated = frame.filename
            lines.append(f'  File "{truncated}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')
        return "\n".join(lines)

    def _format_exception(exc, depth=0):
        if exc is None or depth > 5:
            return ""
        exc_type = type(exc).__name__
        exc_msg = str(exc)
        tb_str = _format_traceback(exc.__traceback__, depth)
        result = f"{exc_type}: {exc_msg}"
        if tb_str:
            result += "\n" + tb_str
        # Handle chained exceptions
        cause = exc.__cause__
        context = exc.__context__
        if cause:
            result += "\nCaused by:\n" + _format_exception(cause, depth + 1)
        elif context and not exc.__suppress_context__:
            result += "\nDuring handling of the above exception, another exception occurred:\n"
            result += _format_exception(context, depth + 1)
        return result

    return _format_exception(e)[:max_level * 200]  # approximate limit to avoid huge output

