def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Determine which classes are superclasses of any other class in the list
    superclasses = set()
    for i, c in enumerate(classes):
        for j, d in enumerate(classes):
            if i != j:
                try:
                    if issubclass(d, c):
                        superclasses.add(c)
                        break
                except TypeError:
                    # If either c or d is not a class, skip comparison
                    continue
    # Return the classes that are not superclasses of any other
    return [c for c in classes if c not in superclasses]

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return attribute names and descriptions defined by the interface.

    Parameters
    ----------
    all : bool, optional
        If True, include attributes from all base classes; otherwise only the
        attributes defined on the current class.

    Returns
    -------
    list[tuple[str, str]]
        A list of (attribute_name, description) tuples sorted by name.
    """
    cls = self.__class__
    classes = cls.mro() if all else [cls]
    descriptions = {}

    for c in classes:
        if c is object:
            continue

        # 1. Look for a mapping of attribute names to descriptions
        attr_desc = getattr(c, "_attribute_descriptions", None)
        if attr_desc is None:
            attr_desc = getattr(c, "__attribute_descriptions__", None)
        if isinstance(attr_desc, dict):
            for name, desc in attr_desc.items():
                if name not in descriptions:
                    descriptions[name] = desc

        # 2. Inspect properties for docstrings
        for name, obj in c.__dict__.items():
            if name.startswith("_"):
                continue
            if isinstance(obj, property):
                desc = obj.fget.__doc__ or ""
                if name not in descriptions:
                    descriptions[name] = desc
            elif callable(obj):
                # Skip methods
                continue
            else:
                # Fallback: use the object's __doc__ if present
                desc = getattr(obj, "__doc__", "")
                if name not in descriptions:
                    descriptions[name] = desc

    # Return sorted list of tuples
    return sorted(descriptions.items())

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if all:
        # Return all attribute names of the instance that are not private or built‑in
        return [name for name in dir(self) if not name.startswith('_')]
    # Return attribute names defined by the interface: class attributes that are not methods
    return [name for name, value in vars(self.__class__).items()
            if not callable(value) and not name.startswith('_')]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Expand nested tuples/lists but treat other objects (including
        # individual interfaces) as atomic.
        if isinstance(item, (tuple, list)):
            _normalizeargs(item, output)
        else:
            output.append(item)
    return output

