def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    # Iterate over points; each point is expected to be a tuple
    # (coordinate, value). If a point is not a tuple, treat it as
    # a coordinate with no value.
    for point in getattr(self, "points", []):
        if isinstance(point, (list, tuple)) and len(point) == 2:
            coord, val = point
        else:
            coord, val = point, None
        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)
        # Convert value to string
        if val is None:
            val_str = ""
        elif isinstance(val, (list, tuple)):
            val_str = separator.join(map(str, val))
        else:
            val_str = str(val)
        # Build CSV line
        if val_str:
            line = coord_str + separator + val_str
        else:
            line = coord_str
        lines.append(line)
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Missing '_err_indices' attribute.")
    err_indices = self._err_indices

    # If error indices are stored in a dictionary keyed by coordinate name
    if isinstance(err_indices, dict):
        if coord_name in err_indices:
            return err_indices[coord_name]
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")

    # If error indices are stored in a list or tuple
    if isinstance(err_indices, (list, tuple)):
        # Determine the index of the coordinate
        if hasattr(self, "coords"):
            coords = self.coords
            if isinstance(coords, dict):
                coord_keys = list(coords.keys())
            else:
                coord_keys = list(coords)
            try:
                idx = coord_keys.index(coord_name)
            except ValueError:
                raise KeyError(f"Coordinate '{coord_name}' not found in coords.")
            if idx < len(err_indices):
                return err_indices[idx]
            raise IndexError(f"Coordinate index {idx} out of range for error indices.")
        else:
            # No coords attribute; assume err_indices is a mapping by name
            try:
                return err_indices[coord_name]
            except (IndexError, KeyError, TypeError):
                raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")

    # If error indices are a NumPy array or any object with ndim
    if hasattr(err_indices, "ndim"):
        if hasattr(self, "coords"):
            coords = self.coords
            if isinstance(coords, dict):
                coord_keys = list(coords.keys())
            else:
                coord_keys = list(coords)
            try:
                idx = coord_keys.index(coord_name)
            except ValueError:
                raise KeyError(f"Coordinate '{coord_name}' not found in coords.")
            return err_indices[idx]
        else:
            try:
                return err_indices[coord_name]
            except Exception:
                raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")

    raise TypeError("Unsupported type for '_err_indices' attribute.")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq is None:
        return False
    # Exclude Source sequences
    if isinstance(seq, Source):
        return False
    # Direct FillRequest instance
    if isinstance(seq, FillRequest):
        return True
    # Check iterable for any FillRequest
    try:
        if isinstance(seq, (str, bytes)):
            return False
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        pass
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, "fill") and callable(getattr(obj, "fill"))
        and hasattr(obj, "request") and callable(getattr(obj, "request"))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    run_attr = getattr(obj, 'run', None)
    return callable(run_attr)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, "fill") and
        hasattr(obj, "compute") and
        callable(getattr(obj, "fill", None)) and
        callable(getattr(obj, "compute", None))
    )

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(d1_sub, d2_sub, lvl):
        result = {}
        for key, val in d1_sub.items():
            if key not in d2_sub:
                result[key] = val
                continue
            val2 = d2_sub[key]
            # If both values are dicts and we are allowed to recurse
            if isinstance(val, dict) and isinstance(val2, dict) and (lvl == -1 or lvl > 1):
                sub = _diff(val, val2, lvl - 1 if lvl > 0 else lvl)
                if sub:
                    result[key] = sub
            else:
                if val != val2:
                    result[key] = val
        return result

    return _diff(d1, d2, level)

