def validate_value(value):
    import re
    pattern = r'^\w+$'
    if not isinstance(value, str):
        raise ValidationError("Value must be a string")
    if not re.fullmatch(pattern, value):
        raise ValidationError(f"Value '{value}' does not match the required pattern")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes
    resource dictionary. All non-dict and non-list values are replaced with None.
    When ``first_level`` is True, the identifying fields of the resource are
    copied from the original manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resource.
        first_level (bool, optional): If True, indicates that the dictionary
            represents the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Lists are handled by a separate function; keep as None here
            result[key] = None
        else:
            # Replace scalar values with None
            result[key] = None

    if first_level:
        # Copy identifying fields from the original manifest
        for id_key in ("apiVersion", "kind", "metadata"):
            if id_key in manifest_dict:
                result[id_key] = manifest_dict[id_key]

    return result

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` dict from a partial
    Kubernetes response based on the provided ``observer_schema``.

    Args:
        last_applied_manifest (dict): The manifest being updated.
        observer_schema (dict): Schema describing which fields to observe.
        response (dict): Partial response from the Kubernetes API.

    Raises:
        KeyError: If an observed field is missing from the response.
    """
    for key, schema in observer_schema.items():
        # Ensure the field exists in the response
        if key not in response:
            raise KeyError(f"Field '{key}' not found in response")

        # If the field is not yet present in the manifest, initialize it
        if key not in last_applied_manifest:
            resp_val = response[key]
            if isinstance(schema, dict):
                # Nested dictionary: create an empty dict and recurse
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema, resp_val
                )
            elif isinstance(schema, list):
                # List: create an empty list and delegate to list handler
                last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema, resp_val
                )
            else:
                # Primitive value: copy directly
                last_applied_manifest[key] = resp_val
        else:
            # Field already exists; ensure nested structures are updated
            if isinstance(schema, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema, response[key]
                )
            elif isinstance(schema, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema, response[key]
                )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the existing observer schema mapping, if any
    existing_schema = getattr(app.spec, "observer_schema", {}) or {}
    # Prepare a dictionary to hold the default schemas
    default_schemas = {}
    # Iterate over all resources in the application's manifest
    for resource in getattr(app.spec, "manifest", []):
        kind = resource.get("kind")
        if not kind:
            continue
        # Skip kinds that already have a custom observer schema
        if kind in existing_schema or kind in default_schemas:
            continue
        # Build a simple default schema that includes common fields
        default_schemas[kind] = {
            "metadata": {
                "name": True,
                "namespace": True,
                "labels": True,
                "annotations": True,
            },
            "spec": True,
            "status": True,
        }
    return default_schemas

def format(self, sql, params):
    # Determine if sql is bytes
    is_bytes = isinstance(sql, bytes)
    if is_bytes:
        sql_str = sql.decode('utf-8')
    else:
        sql_str = sql

    in_style = getattr(self, 'in_style', None)
    out_style = getattr(self, 'out_style', None)

    # If styles are the same, return unchanged
    if in_style == out_style:
        return (sql, params)

    # Helper to parse named placeholders (:name or %(name)s)
    def parse_named(s):
        placeholders = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == ':':
                j = i + 1
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                if j > i + 1:
                    placeholders.append((i, j, s[i+1:j]))
                    i = j
                    continue
            elif s[i] == '%' and i + 1 < n and s[i+1] == '(':
                j = i + 2
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                if j < n and s[j] == ')' and j + 1 < n and s[j+1] == 's':
                    placeholders.append((i, j + 2, s[i+2:j]))
                    i = j + 2
                    continue
            i += 1
        return placeholders

    # Helper to parse ordinal placeholders (? or %s)
    def parse_ordinal(s):
        placeholders = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == '?':
                placeholders.append((i, i + 1, None))
                i += 1
                continue
            elif s[i] == '%' and i + 1 < n and s[i+1] == 's':
                placeholders.append((i, i + 2, None))
                i += 2
                continue
            i += 1
        return placeholders

    # Conversion logic
    if in_style == 'named' and out_style in ('qmark', 'format'):
        # Replace named placeholders with '?' or '%s'
        placeholders = parse_named(sql_str)
        new_sql_parts = []
        last = 0
        out_params = []
        for start, end, name in placeholders:
            new_sql_parts.append(sql_str[last:start])
            if out_style == 'qmark':
                new_sql_parts.append('?')
                placeholder = '?'
            else:  # format
                new_sql_parts.append('%s')
                placeholder = '%s'
            last = end
            # Retrieve value from params dict
            if isinstance(params, dict):
                out_params.append(params.get(name))
            else:
                # If params is not a dict, cannot map by name
                out_params.append(None)
        new_sql_parts.append(sql_str[last:])
        new_sql = ''.join(new_sql_parts)
        if out_style == 'qmark':
            out_params = list(out_params)
        else:
            out_params = list(out_params)
        result_sql = new_sql.encode('utf-8') if is_bytes else new_sql
        return (result_sql, out_params)

    if in_style == 'ordinal' and out_style == 'named':
        # Replace ordinal placeholders with :1, :2, ...
        placeholders = parse_ordinal(sql_str)
        new_sql_parts = []
        last = 0
        out_params = {}
        for idx, (start, end, _) in enumerate(placeholders, start=1):
            new_sql_parts.append(sql_str[last:start])
            new_sql_parts.append(f':{idx}')
            last = end
            # Retrieve value from params sequence
            if isinstance(params, (list, tuple)):
                out_params[idx] = params[idx - 1]
            else:
                out_params[idx] = None
        new_sql_parts.append(sql_str[last:])
        new_sql = ''.join(new_sql_parts)
        result_sql = new_sql.encode('utf-8') if is_bytes else new_sql
        return (result_sql, out_params)

    # Fallback: if conversion not supported, return original
    return (sql, params)

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    import re
    # Determine placeholder regex for the input style
    if self.in_style == "qmark":
        pattern = re.compile(r"\?")
    elif self.in_style == "named":
        pattern = re.compile(r":([A-Za-z_][A-Za-z0-9_]*)")
    elif self.in_style == "numeric":
        pattern = re.compile(r":(\d+)")
    elif self.in_style == "pyformat":
        pattern = re.compile(r"%\(([^)]+)\)s")
    elif self.in_style == "format":
        pattern = re.compile(r"%s")
    else:
        raise ValueError(f"Unsupported in_style: {self.in_style}")

    # Work with a string for regex processing
    is_bytes = isinstance(sql, bytes)
    sql_str = sql.decode("utf-8") if is_bytes else sql

    # Find all placeholders in order
    placeholders = []
    for m in pattern.finditer(sql_str):
        if self.in_style in ("qmark", "format"):
            placeholders.append(None)
        else:
            placeholders.append(m.group(1))

    # Build the new SQL string with out_style placeholders
    new_sql_parts = []
    last_end = 0
    for i, m in enumerate(pattern.finditer(sql_str)):
        new_sql_parts.append(sql_str[last_end : m.start()])
        if self.out_style == "qmark":
            rep = "?"
        elif self.out_style == "named":
            name = placeholders[i]
            if name is None:
                name = f"param{i + 1}"
            rep = f":{name}"
        elif self.out_style == "numeric":
            rep = f":{i + 1}"
        elif self.out_style == "format":
            rep = "%s"
        elif self.out_style == "pyformat":
            name = placeholders[i]
            if name is None:
                name = f"param{i + 1}"
            rep = f"%({name})s"
        else:
            raise ValueError(f"Unsupported out_style: {self.out_style}")
        new_sql_parts.append(rep)
        last_end = m.end()
    new_sql_parts.append(sql_str[last_end:])
    new_sql_str = "".join(new_sql_parts)

    # Convert parameters for each set
    converted = []
    for params in many_params:
        # Determine if params is a mapping or a sequence
        is_mapping = isinstance(params, dict)
        if is_mapping:
            if self.out_style in ("qmark", "format"):
                # Positional list
                vals = []
                for ph in placeholders:
                    key = ph
                    if key is None:
                        raise ValueError("Cannot map unnamed placeholder to mapping")
                    if key not in params:
                        raise KeyError(f"Missing key {key} in parameters")
                    vals.append(params[key])
                converted.append(vals)
            else:
                # Named dict
                d = {}
                for ph in placeholders:
                    key = ph
                    if key is None:
                        key = f"param{placeholders.index(ph) + 1}"
                    if key not in params:
                        raise KeyError(f"Missing key {key} in parameters")
                    d[key] = params[key]
                converted.append(d)
        else:
            # Treat as sequence
            seq = list(params)
            if self.out_style in ("qmark", "format"):
                if len(seq) != len(placeholders):
                    raise ValueError("Parameter count mismatch")
                converted.append(seq)
            else:
                d = {}
                for i, ph in enumerate(placeholders):
                    key = ph
                    if key is None:
                        key = f"param{i + 1}"
                    d[key] = seq[i]
                converted.append(d)

    # Encode back to bytes if original was bytes
    if is_bytes:
        new_sql = new_sql_str.encode("utf-8")
    else:
        new_sql = new_sql_str

    return new_sql, converted

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Try to get a status attribute
    status = getattr(self, 'status', None)

    # If status is a boolean, convert to a readable string
    if isinstance(status, bool):
        status = 'OK' if status else 'ERROR'

    # If no status attribute, fall back to a 'valid' boolean if present
    if status is None:
        if hasattr(self, 'valid'):
            status = 'OK' if self.valid else 'ERROR'
        else:
            status = 'UNKNOWN'

    # Append an error or message if available
    error = getattr(self, 'error', None)
    if error:
        status = f"{status}: {error}"
    elif hasattr(self, 'message') and getattr(self, 'message'):
        status = f"{status}: {self.message}"

    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Retrieve the log attribute, supporting common naming conventions
    log = getattr(self, 'log', None) or getattr(self, '_log', None)
    if not log:
        return ''
    lines = []
    if isinstance(log, str):
        lines.append(prefix + log)
    elif isinstance(log, (list, tuple)):
        for item in log:
            if isinstance(item, tuple) and len(item) == 2:
                level, msg = item
                lines.append(prefix + f"{level}: {msg}")
            else:
                lines.append(prefix + str(item))
    elif isinstance(log, dict):
        for key, value in log.items():
            lines.append(prefix + f"{key}: {value}")
    else:
        lines.append(prefix + str(log))
    return '\n'.join(lines)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Try to infer spec version from the type string
            if "v1" in type_val.lower():
                spec_version = "1.0"
            elif "v2" in type_val.lower():
                spec_version = "2.0"
            else:
                # Fallback to the instance's spec_version
                spec_version = self.spec_version
        else:
            spec_version = self.spec_version

    # Required top‑level fields
    required_fields = ["name", "description", "components"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")

    # Validate name
    name = inventory["name"]
    if not isinstance(name, str) or not name.strip():
        raise ValueError("name must be a non‑empty string")

    # Validate description
    description = inventory["description"]
    if not isinstance(description, str):
        raise ValueError("description must be a string")

    # Validate components
    components = inventory["components"]
    if not isinstance(components, list):
        raise ValueError("components must be a list")
    for idx, comp in enumerate(components):
        if not isinstance(comp, dict):
            raise ValueError(f"Component at index {idx} must be a dict")
        # Component required fields
        comp_req = ["name", "type", "properties"]
        for cf in comp_req:
            if cf not in comp:
                raise ValueError(f"Component at index {idx} missing required field: {cf}")
        # Validate component name
        comp_name = comp["name"]
        if not isinstance(comp_name, str) or not comp_name.strip():
            raise ValueError(f"Component name at index {idx} must be a non‑empty string")
        # Validate component type
        comp_type = comp["type"]
        if not isinstance(comp_type, str) or not comp_type.strip():
            raise ValueError(f"Component type at index {idx} must be a non‑empty string")
        # Validate component properties
        comp_props = comp["properties"]
        if not isinstance(comp_props, dict):
            raise ValueError(f"Component properties at index {idx} must be a dict")

    # Validate spec version against allowed values
    allowed_versions = ["1.0", "2.0"]
    if spec_version not in allowed_versions:
        raise ValueError(f"Unsupported spec_version: {spec_version}")

    # Update instance spec_version if we extracted it
    if extract_spec_version:
        self.spec_version = spec_version

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure the prior version is older than the current one
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise ValueError("both inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError("prior version must be older than the current version")

    # Ensure the prior inventory is a subset of the current inventory
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise ValueError("both inventories must have an 'inventory' attribute")
    try:
        current_set = set(self.inventory)
        prior_set = set(prior.inventory)
    except Exception as exc:
        raise ValueError("inventory attributes must be iterable") from exc

    if not prior_set.issubset(current_set):
        raise ValueError("prior inventory is not a subset of the current inventory")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    # Helper to convert a value to int safely
    def to_int(v):
        try:
            return int(v)
        except Exception:
            return None

    # If inventory is a list of entries
    if isinstance(inventory, list):
        # Group entries by logical_path
        groups = {}
        for entry in inventory:
            lp = entry.get('logical_path')
            if lp is None:
                continue
            groups.setdefault(lp, []).append(entry)
        for lp, entries in groups.items():
            best_version = None
            for e in entries:
                v = to_int(e.get('version'))
                if v is None:
                    continue
                if v <= version and (best_version is None or v > best_version):
                    best_version = v
            if best_version is not None:
                files = {e.get('content_file') for e in entries
                         if to_int(e.get('version')) == best_version}
                # Remove None entries
                files.discard(None)
                result[lp] = files
        return result

    # If inventory is a dict
    if isinstance(inventory, dict):
        for lp, data in inventory.items():
            # Data could be a dict of version -> content_file
            if isinstance(data, dict):
                best_version = None
                for v_str, cf in data.items():
                    v = to_int(v_str)
                    if v is None:
                        continue
                    if v <= version and (best_version is None or v > best_version):
                        best_version = v
                if best_version is not None:
                    cf = data.get(str(best_version))
                    if cf is not None:
                        result[lp] = {cf}
                continue

            # Data could be a list of entries
            if isinstance(data, list):
                best_version = None
                for entry in data:
                    if isinstance(entry, dict):
                        v = to_int(entry.get('version'))
                    else:
                        # Assume tuple (content_file, version)
                        if len(entry) == 2:
                            _, v = entry
                            v = to_int(v)
                        else:
                            v = None
                    if v is None:
                        continue
                    if v <= version and (best_version is None or v > best_version):
                        best_version = v
                if best_version is not None:
                    files = set()
                    for entry in data:
                        if isinstance(entry, dict):
                            v = to_int(entry.get('version'))
                            if v == best_version:
                                cf = entry.get('content_file')
                                if cf is not None:
                                    files.add(cf)
                        else:
                            if len(entry) == 2:
                                cf, v = entry
                                v = to_int(v)
                                if v == best_version and cf is not None:
                                    files.add(cf)
                    if files:
                        result[lp] = files
                continue

    return result

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        entries = os.listdir(path)
    except OSError:
        return []
    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path):
            files.append(entry)
    return files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    result = {}
    try:
        entries = os.listdir(folder)
    except Exception:
        return result
    groups = {}
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue
        name, ext = os.path.splitext(entry)
        groups.setdefault(name, []).append(full_path)
    for name, paths in groups.items():
        if any(p.lower().endswith('.xml') for p in paths):
            result[name] = paths
    return result

def add_asset(self, basename, file_path):
    if not hasattr(self, 'assets'):
        self.assets = {}
    self.assets[basename] = file_path

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        return content
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if not result:
            continue
        first = result[0]
        if isinstance(first, str):
            value = first.strip()
        else:
            # If it's an element, get its text content
            value = (first.text or "").strip()
        if value:
            return value
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()
    def _pretty(obj, current_indent):
        if id(obj) in visited:
            return current_indent + '<Circular Reference>'
        visited.add(id(obj))
        if isinstance(obj, dict):
            lines = [f'{current_indent}{{']
            for k, v in obj.items():
                lines.append(f'{current_indent}  {repr(k)}: {_pretty(v, current_indent + "  ")}')
            lines.append(f'{current_indent}}}')
            return '\n'.join(lines)
        elif isinstance(obj, list):
            lines = [f'{current_indent}[']
            for v in obj:
                lines.append(f'{current_indent}  {_pretty(v, current_indent + "  ")}')
            lines.append(f'{current_indent}]')
            return '\n'.join(lines)
        elif isinstance(obj, tuple):
            lines = [f'{current_indent}(']
            for v in obj:
                lines.append(f'{current_indent}  {_pretty(v, current_indent + "  ")}')
            lines.append(f'{current_indent})')
            return '\n'.join(lines)
        elif isinstance(obj, set):
            lines = [f'{current_indent}{{']
            for v in obj:
                lines.append(f'{current_indent}  {_pretty(v, current_indent + "  ")}')
            lines.append(f'{current_indent}}}')
            return '\n'.join(lines)
        elif hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            lines = [f'{current_indent}{cls_name}(']
            for k, v in obj.__dict__.items():
                lines.append(f'{current_indent}  {k} = {_pretty(v, current_indent + "  ")}')
            lines.append(f'{current_indent})')
            return '\n'.join(lines)
        else:
            if debug:
                return f'{current_indent}{repr(obj)} (type={type(obj).__name__})'
            else:
                return f'{current_indent}{repr(obj)}'
    return _pretty(self, ' ' * indent)

def absorb(self, args):
    new_args = []
    for expr in args:
        simplified = expr
        if hasattr(expr, 'func') and hasattr(expr, 'args'):
            op_name = expr.func.__name__
            if op_name in ('And', 'Or'):
                left, right = expr.args
                # Absorption
                if op_name == 'And':
                    # left is Or
                    if hasattr(left, 'func') and left.func.__name__ == 'Or':
                        a, b = left.args
                        if a == right or b == right:
                            simplified = right
                    # right is Or
                    if hasattr(right, 'func') and right.func.__name__ == 'Or':
                        a, b = right.args
                        if a == left or b == left:
                            simplified = left
                    # Negative absorption
                    if hasattr(right, 'func') and right.func.__name__ == 'Or':
                        a, b = right.args
                        if hasattr(a, 'func') and a.func.__name__ == 'Not' and a.args[0] == left:
                            simplified = expr.func(left, b)
                        if hasattr(b, 'func') and b.func.__name__ == 'Not' and b.args[0] == left:
                            simplified = expr.func(left, a)
                    if hasattr(left, 'func') and left.func.__name__ == 'Or':
                        a, b = left.args
                        if hasattr(a, 'func') and a.func.__name__ == 'Not' and a.args[0] == right:
                            simplified = expr.func(right, b)
                        if hasattr(b, 'func') and b.func.__name__ == 'Not' and b.args[0] == right:
                            simplified = expr.func(right, a)
                elif op_name == 'Or':
                    # left is And
                    if hasattr(left, 'func') and left.func.__name__ == 'And':
                        a, b = left.args
                        if a == right or b == right:
                            simplified = right
                    # right is And
                    if hasattr(right, 'func') and right.func.__name__ == 'And':
                        a, b = right.args
                        if a == left or b == left:
                            simplified = left
                    # Negative absorption
                    if hasattr(right, 'func') and right.func.__name__ == 'And':
                        a, b = right.args
                        if hasattr(a, 'func') and a.func.__name__ == 'Not' and a.args[0] == left:
                            simplified = expr.func(left, b)
                        if hasattr(b, 'func') and b.func.__name__ == 'Not' and b.args[0] == left:
                            simplified = expr.func(left, a)
                    if hasattr(left, 'func') and left.func.__name__ == 'And':
                        a, b = left.args
                        if hasattr(a, 'func') and a.func.__name__ == 'Not' and a.args[0] == right:
                            simplified = expr.func(right, b)
                        if hasattr(b, 'func') and b.func.__name__ == 'Not' and b.args[0] == right:
                            simplified = expr.func(right, a)
        new_args.append(simplified)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    result = namefunc()
    try:
        # In Python 2, unicode type exists
        if isinstance(result, unicode):
            return result.encode('utf-8')
    except NameError:
        # In Python 3, unicode is not defined; no conversion needed
        pass
    return result

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to get the version from package metadata
    try:
        import importlib.metadata as metadata
        # Use the package name from the module's __package__ or __name__
        pkg_name = __package__ or __name__
        version = metadata.version(pkg_name)
    except Exception:
        # Fallback: try to read a VERSION file in the same directory
        try:
            import os
            base_dir = os.path.abspath(os.path.dirname(__file__)) if '__file__' in globals() else os.getcwd()
            with open(os.path.join(base_dir, 'VERSION'), 'r', encoding='utf-8') as f:
                version = f.read().strip()
        except Exception:
            # Final fallback: use a hard‑coded default
            version = '0.0.0'
    return {'version': version}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '+' if '+' not in pieces else '.'

def register_vcs_handler(vcs):
    def decorator(method):
        registry[vcs] = method
        return method
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Retrieve the collection of objects to validate.  If the attribute does not exist,
    # fall back to an empty list so the method still works.
    objects = getattr(self, "objects", [])

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Object-level validation
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    is_valid = obj.validate()
                elif hasattr(self, "_validate_object") and callable(self._validate_object):
                    is_valid = self._validate_object(obj)
                else:
                    # No explicit validation method; assume valid
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    name = getattr(obj, "name", str(obj))
                    print(f"Warning: validation failed for {name}: {exc}")

        # Digest check
        if check_digests:
            try:
                import hashlib
                data = getattr(obj, "data", None)
                if data is not None:
                    # Compute SHA-256 digest of the data
                    digest = hashlib.sha256(data).hexdigest()
                    expected = getattr(obj, "digest", None)
                    if expected != digest:
                        is_valid = False
                        if show_warnings:
                            name = getattr(obj, "name", str(obj))
                            print(f"Warning: digest mismatch for {name}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    name = getattr(obj, "name", str(obj))
                    print(f"Warning: digest check failed for {name}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"Path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        namaste_path = os.path.join(path, "0=*")
        if not os.path.isfile(namaste_path):
            return f"No Namaste file found in directory: {path}"
        try:
            with open(namaste_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read().strip()
        except Exception as e:
            return f"Error reading Namaste file: {e}"
        if "OCFL Storage Root" in content:
            return 'root'
        if "OCFL Object" in content:
            return 'object'
        return f"Unknown Namaste file content in {namaste_path}"
    return f"Unsupported path type: {path}"

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values
    for duplicate keys. Non-mapping values are overwritten by the last one.
    """
    def merge_values(v1, v2):
        # If both are MappingNode, deep merge their contents
        if isinstance(v1, ruamel.yaml.nodes.MappingNode) and isinstance(v2, ruamel.yaml.nodes.MappingNode):
            # Build dicts of key.value -> node for existing and new
            existing_dict = {k.value: (k, val) for k, val in v1.value}
            new_dict = {k.value: (k, val) for k, val in v2.value}
            # Merge new into existing
            for key, (k_node, new_val) in new_dict.items():
                if key in existing_dict:
                    _, existing_val = existing_dict[key]
                    merged_val = merge_values(existing_val, new_val)
                    existing_dict[key] = (k_node, merged_val)
                else:
                    existing_dict[key] = (k_node, new_val)
            # Preserve order: start with existing order, then append new keys not present
            merged_list = []
            seen_keys = set()
            for k_node, val in v1.value:
                key = k_node.value
                merged_list.append((k_node, existing_dict[key][1]))
                seen_keys.add(key)
            for key, (k_node, val) in new_dict.items():
                if key not in seen_keys:
                    merged_list.append((k_node, val))
            return ruamel.yaml.nodes.MappingNode(tag=v1.tag, value=merged_list)
        # Otherwise, last value wins
        return v2

    result = []
    seen = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in seen:
            existing_key_node, existing_val_node = seen[key]
            merged_val = merge_values(existing_val_node, val_node)
            seen[key] = (existing_key_node, merged_val)
        else:
            seen[key] = (key_node, val_node)
    # Preserve original order of first occurrence
    for key, (k_node, v_node) in seen.items():
        result.append((k_node, v_node))
    return result

def parser_flags(parser):
