def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging MappingNode values
    recursively for duplicate keys. Non-MappingNode values are overwritten by
    the last occurrence.
    """
    # Helper to merge two MappingNode values
    def merge_mapping_nodes(existing_map, new_map):
        """
        existing_map and new_map are lists of (ScalarNode, value) tuples.
        Merge new_map into existing_map in place.
        """
        # Build a dict for existing mapping to allow quick lookup
        existing_dict = {k.value: (k, v) for k, v in existing_map}
        for new_key, new_val in new_map:
            if new_key.value in existing_dict:
                _, existing_val = existing_dict[new_key.value]
                # If both are MappingNode, merge recursively
                if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(new_val, ruamel.yaml.nodes.MappingNode):
                    merge_mapping_nodes(existing_val.value, new_val.value)
                else:
                    # Replace with new value
                    existing_dict[new_key.value] = (new_key, new_val)
            else:
                # New key, append
                existing_dict[new_key.value] = (new_key, new_val)
        # Rebuild list preserving order of existing keys, then new keys
        merged = []
        seen = set()
        for k, v in existing_map:
            if k.value in seen:
                continue
            seen.add(k.value)
            merged.append((k, v))
        for k, v in new_map:
            if k.value not in seen:
                merged.append((k, v))
        return merged

    # Main merge
    merged_nodes = []
    key_order = []
    key_map = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_map:
            existing_key_node, existing_val_node = key_map[key]
            if isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                # Merge mapping nodes
                merged_map = merge_mapping_nodes(existing_val_node.value, val_node.value)
                existing_val_node.value = merged_map
            else:
                # Replace with new value
                key_map[key] = (key_node, val_node)
        else:
            key_map[key] = (key_node, val_node)
            key_order.append(key)
    # Build result preserving order
    result = []
    for key in key_order:
        result.append(key_map[key])
    return result

