def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Negative numbers are not supported")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")
    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        # digits are least significant first, reverse to get most significant first
        result = ''.join(reversed(digits))
    # Apply padding if requested
    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative")
        pad_char = alphabet[0]
        if len(result) < padding:
            result = pad_char * (padding - len(result)) + result
    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        return value
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    base = len(alphabet)
    # Build a mapping from character to its numeric value
    char_to_value = {c: i for i, c in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not in alphabet")
        result = result * base + char_to_value[ch]
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r"(^['\"]|['\"]$)", "", name)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string checks for common localhost identifiers
    if host.lower() == 'localhost':
        return True
    if host == '127.0.0.1' or host == '::1':
        return True
    try:
        # Resolve the host to all possible addresses
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == '127.0.0.1':
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == '::1':
                return True
    return False

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if strip:
        pattern = pattern.strip()
    return re.escape(pattern)

def is_ipv4(target):
