def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2)**2) / (2 * 0.1**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Load and validate configuration files.

    Parameters
    ----------
    config_filenames : iterable
        Sequence of configuration file paths.
    overrides : dict, optional
        Dictionary of key/value pairs to override parsed configuration.
    resolve_env : bool, optional
        If True, resolve environment variable placeholders of the form ${VAR}.

    Returns
    -------
    tuple
        (config_dict, error_records)
        config_dict : dict
            Mapping from filename to parsed configuration dictionary.
        error_records : list
            List of logging.LogRecord instances for any parse errors.
    """
    import json
    import os
    import re
    import logging

    config_dict = {}
    error_records = []

    # Helper to resolve environment variables in a string
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, value)
        return value

    # Helper to recursively resolve env vars in dict/list
    def resolve_in_obj(obj):
        if isinstance(obj, dict):
            return {k: resolve_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_in_obj(v) for v in obj]
        else:
            return resolve_env_vars(obj)

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if resolve_env:
                data = resolve_in_obj(data)
            # Apply overrides if provided
            if overrides:
                if isinstance(data, dict):
                    data.update(overrides)
                else:
                    # If data is not a dict, we cannot apply overrides
                    pass
            config_dict[filename] = data
        except Exception as exc:
            # Create a LogRecord for the error
            logger_name = 'config_loader'
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return config_dict, error_records

def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight)."""
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an int")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    seconds, ns = divmod(ticks, 1_000_000_000)
    hour = seconds // 3600
    minute = (seconds % 3600) // 60
    second = seconds % 60
    microsecond = ns // 1000
    kwargs = {
        "hour": hour,
        "minute": minute,
        "second": second,
        "microsecond": microsecond,
    }
    if tz is not None:
        kwargs["tzinfo"] = tz
    return cls(**kwargs)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram to a graph representation.

    Parameters
    ----------
    hist : object
        Histogram object. It must provide either a ``bins`` attribute
        (an iterable of bin objects with ``left``, ``right`` and
        ``content`` attributes) or the attributes ``left_edges``,
        ``right_edges`` and ``contents``.
    make_value : callable, optional
        Function that transforms a bin content into the value(s) to be
        stored in the graph.  If ``None`` the bin content is used
        directly.
    get_coordinate : {"left", "right", "middle"}, default "left"
        Which coordinate of the bin to use as the graph point's
        independent variable.
    field_names : tuple of str, default ("x", "y")
        Names of the fields in the resulting graph.  The first name
        corresponds to the coordinate, the remaining names correspond
        to the values returned by ``make_value``.
    scale : bool or any, default None
        If ``True`` the graph inherits the histogram's scale
        (``hist.scale`` if present).  Otherwise the value is used
        directly.

    Returns
    -------
    dict
        A simple graph representation with keys ``field_names``,
        ``points`` and ``scale``.
    """
    if make_value is None:
        make_value = lambda v: v

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    # Helper to access attributes or dict keys
    def _get(obj, name):
        if isinstance(obj, dict):
            return obj.get(name)
        return getattr(obj, name)

    # Retrieve bins
    if hasattr(hist, "bins"):
        bins = hist.bins
    else:
        left_edges = getattr(hist, "left_edges", None)
        right_edges = getattr(hist, "right_edges", None)
        contents = getattr(hist, "contents", None)
        if left_edges is None or right_edges is None or contents is None:
            raise AttributeError(
                "Histogram must provide 'bins' or 'left_edges', 'right_edges', 'contents'"
            )
        bins = [
            {"left": l, "right": r, "content": c}
            for l, r, c in zip(left_edges, right_edges, contents)
        ]

    points = []
    for bin_ in bins:
        left = _get(bin_, "left")
        right = _get(bin_, "right")
        content = _get(bin_, "content")

        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = (left + right) / 2

        val = make_value(content)

        # Build point dictionary
        if isinstance(val, (tuple, list)):
            if len(val) + 1 != len(field_names):
                raise ValueError(
                    "Number of values returned by make_value does not match field_names"
                )
            point = {field_names[0]: coord}
            for i, v in enumerate(val):
                point[field_names[i + 1]] = v
        else:
            if len(field_names) != 2:
                raise ValueError(
                    "field_names must have length 2 when make_value returns a scalar"
                )
            point = {field_names[0]: coord, field_names[1]: val}

        points.append(point)

    # Determine scale
    if scale is True:
        scale = getattr(hist, "scale", None)

    return {"field_names": field_names, "points": points, "scale": scale}

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    # Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy: {exc!r}")
    # Prepare helpers
    Method = __import__('zope.interface').interfaces.Method
    inspect = __import__('inspect')
    # Iterate over interface attributes and methods
    for name in iface.names():
        attr = iface.getAttribute(name)
        if isinstance(attr, Method):
            # Method check
            if not hasattr(candidate, name):
                errors.append(f"Missing method {name!r} in {candidate!r}")
                continue
            method = getattr(candidate, name)
            if not callable(method):
                errors.append(f"{name!r} in {candidate!r} is not callable")
                continue
            # Signature check if interface specifies one
            if attr.signature is not None:
                try:
                    cand_sig = str(inspect.signature(method)).strip()
                except Exception as exc:
                    errors.append(f"Could not inspect signature of {name!r}: {exc!r}")
                    continue
                iface_sig = attr.signature.strip()
                # Remove surrounding parentheses
                if cand_sig.startswith('(') and cand_sig.endswith(')'):
                    cand_sig = cand_sig[1:-1]
                if iface_sig.startswith('(') and iface_sig.endswith(')'):
                    iface_sig = iface_sig[1:-1]
                cand_sig = cand_sig.strip()
                iface_sig = iface_sig.strip()
                # Remove leading 'self' if present
                if cand_sig.startswith('self'):
                    cand_sig = cand_sig[5:].lstrip(',').strip()
                if cand_sig != iface_sig:
                    errors.append(
                        f"Signature mismatch for {name!r}: expected {iface_sig!r}, got {cand_sig!r}"
                    )
        else:
            # Attribute check
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute {name!r} in {candidate!r}")
    # Raise collected errors if any
    if errors:
        Invalid = __import__('zope.interface').Invalid
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate is a class that implements all public
    attributes of iface (or is a subclass of iface). If tentative is
    True, missing attributes are ignored.
    """
    # candidate must be a class
    if not isinstance(candidate, type):
        return False
    # If iface is a class, check subclass relationship
    if isinstance(iface, type):
        if issubclass(candidate, iface):
            return True
    # Get public attributes of iface
    iface_attrs = [name for name in dir(iface) if not name.startswith('_')]
    for name in iface_attrs:
        if not hasattr(candidate, name):
            if tentative:
                continue
            return False
        iface_val = getattr(iface, name)
        cand_val = getattr(candidate, name)
        # Skip abstract methods
        if getattr(iface_val, "__isabstractmethod__", False):
            continue
        # If iface defines a method, ensure candidate's attribute is callable
        if callable(iface_val) and not callable(cand_val):
            if tentative:
                continue
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it directly.
    if explicit_mc is not None:
        return explicit_mc

    # Gather the metaclasses of all bases.
    metaclasses = [type(b) for b in bases]

    # Find the most derived metaclass: the one that is a subclass of all others.
    candidates = []
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            candidates.append(mc)

    if len(candidates) == 1:
        return candidates[0]
    if len(candidates) == 0:
        raise TypeError("metaclass conflict: no metaclass found")
    # Multiple candidates means a conflict.
    raise TypeError("metaclass conflict: multiple metaclasses found")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self._data:
        return self._data.pop(key)
    if default is __marker:
        raise KeyError(key)
    return default

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to use the cache attribute (common names: cache, _cache)
    cache = getattr(self, 'cache', None) or getattr(self, '_cache', None)
    if cache is None:
        raise AttributeError("No cache attribute found on the instance.")
    # If the cache is an OrderedDict (or similar) that supports popitem(last=False)
    try:
        return cache.popitem(last=False)
    except TypeError:
        # Fallback: use the first key in the dict (may not be LRU if not ordered)
        key = next(iter(cache))
        value = cache.pop(key)
        return key, value

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check public message first
    try:
        public = getattr(request, "public", None)
        if public:
            # Assume public is a dict-like object
            if isinstance(public, dict):
                if public.get("diaspora") or public.get("type") == "diaspora":
                    return True
            # If public is an object with attributes
            if hasattr(public, "diaspora") or getattr(public, "type", None) == "diaspora":
                return True
    except Exception:
        pass

    # Check private message next
    try:
        private = getattr(request, "private", None)
        if private:
            if isinstance(private, dict):
                if private.get("diaspora") or private.get("type") == "diaspora":
                    return True
            if hasattr(private, "diaspora") or getattr(private, "type", None) == "diaspora":
                return True
    except Exception:
        pass

    # Finally check legacy payload
    try:
        payload = getattr(request, "payload", None)
        if payload:
            if isinstance(payload, dict):
                legacy = payload.get("legacy")
                if legacy and isinstance(legacy, dict):
                    if legacy.get("diaspora"):
                        return True
            if hasattr(payload, "legacy"):
                legacy = getattr(payload, "legacy")
                if legacy and getattr(legacy, "diaspora", False):
                    return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Common Matrix request keys
            if "type" in request and "content" in request:
                if isinstance(request["type"], str) and request["type"].startswith("m."):
                    return True
            if "room_id" in request or "event_id" in request:
                return True
        # Handle object-like requests
        if hasattr(request, "type") and hasattr(request, "content"):
            if isinstance(request.type, str) and request.type.startswith("m."):
                return True
        return False
    except Exception:
        return False

def process_text_links(text):
    import re
    # Add target and rel attributes to existing <a> tags
    def add_attrs(match):
        tag = match.group(0)
        if 'target=' in tag:
            return tag
        return tag[:-1] + ' target="_blank" rel="noopener noreferrer">'
    text = re.sub(r'<a\b[^>]*>', add_attrs, text)

    # Regular expression to find URLs in plain text
    url_re = re.compile(r'\b((?:https?://|www\.)[^\s<]+)')

    # Keep a copy of the text after adding attributes for context checks
    original_text = text

    def repl(match):
        url = match.group(1)
        href = url
        if url.startswith('www.'):
            href = 'http://' + url
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

    def replace_if_not_in_tag(match):
        start = match.start()
        # Find the last '<' before the match
        last_lt = original_text.rfind('<', 0, start)
        if last_lt != -1:
            # If there is no '>' after that '<' before the match, we are inside a tag
            if '>' not in original_text[last_lt:start]:
                return match.group(0)  # leave unchanged
        return repl(match)

    text = url_re.sub(replace_if_not_in_tag, text)
    return text

def fetch_content_type(url: str) -> Optional[str]:
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Empty tags are not allowed
    if not tag:
        return False

    # Maximum length constraint (example: 30 characters)
    if len(tag) > 30:
        return False

    # Allowed characters: lowercase letters, digits, and hyphens
    # No leading or trailing hyphens, and no consecutive hyphens
    prev_char = ''
    for i, ch in enumerate(tag):
        if ch.islower() or ch.isdigit() or ch == '-':
            if ch == '-':
                # Hyphen cannot be first or last
                if i == 0 or i == len(tag) - 1:
                    return False
                # No consecutive hyphens
                if prev_char == '-':
                    return False
        else:
            return False
        prev_char = ch

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If we already have a single element, convert to list
            if not isinstance(result[key], list):
                result[key] = [result[key]]
            result[key].append(child)
        else:
            result[key] = child
    return result

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    from lxml import etree
    import xmlsec

    # Parse the XML document if it is a string
    if isinstance(doc, str):
        try:
            doc_root = etree.fromstring(doc)
        except Exception as e:
            raise ValueError(f"Invalid XML document: {e}")
    else:
        doc_root = doc

    # Parse the signature element if it is a string
    if isinstance(signature, str):
        try:
            sig_root = etree.fromstring(signature)
        except Exception as e:
            raise ValueError(f"Invalid signature XML: {e}")
    else:
        sig_root = signature

    # Create a signature context for verification
    ctx = xmlsec.SignatureContext()

    # Load the public key (PEM format expected)
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {e}")
    ctx.key = key

    # Find the signature node in the document if not provided explicitly
    if sig_root is None:
        sig_node = xmlsec.tree.find_node(doc_root, xmlsec.Node.SIGNATURE)
        if sig_node is None:
            raise ValueError("No signature node found in the document")
    else:
        sig_node = sig_root

    # Perform the verification
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as e:
        raise RuntimeError(f"Signature verification failed: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        data = json.loads(document)
        subject = data.get("subject", "")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        # Ensure links are list of dicts
        if isinstance(links, dict):
            links = [links]
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        pass

    # Fallback to XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        # Namespace handling: XRD may use default namespace
        ns = {}
        if root.tag.startswith("{"):
            uri, _, tag = root.tag[1:].partition("}")
            ns = {"ns": uri}
            subject_elem = root.find("ns:subject", ns)
            alias_elems = root.findall("ns:alias", ns)
            link_elems = root.findall("ns:link", ns)
        else:
            subject_elem = root.find("subject")
            alias_elems = root.findall("alias")
            link_elems = root.findall("link")

        subject = subject_elem.text if subject_elem is not None else ""
        aliases = [e.text for e in alias_elems if e.text]
        links = []
        for e in link_elems:
            # Convert attributes to dict
            link = dict(e.attrib)
            # Some XRD link elements may have nested <meta> elements; ignore for now
            links.append(link)
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception as exc:
        raise ValueError(f"Unable to parse Diaspora webfinger: {exc}") from exc

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Use the specified HTTP method; default to POST
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option=None):
    """Return a list of file paths from the given directories, optionally filtered by spec_option.

    Parameters
    ----------
    settings_dirs : Iterable[str]
        Directories to search for files.
    spec_option : str or callable or None, optional
        If str, treated as a glob pattern (e.g., '*.ini').
        If callable, used as a filter function that receives a file path and returns bool.
        If None, no filtering.

    Returns
    -------
    List[str]
        List of file paths.
    """
    import os
    import fnmatch

    file_list = []
    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        for entry in os.listdir(dir_path):
            full_path = os.path.join(dir_path, entry)
            if not os.path.isfile(full_path):
                continue
            if spec_option is None:
                file_list.append(full_path)
            elif isinstance(spec_option, str):
                if fnmatch.fnmatch(entry, spec_option):
                    file_list.append(full_path)
            elif callable(spec_option):
                try:
                    if spec_option(full_path):
                        file_list.append(full_path)
                except Exception:
                    pass
    return file_list

