def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file path provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"YAML file not found: {yaml_file}")
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file: {exc}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping")

        # Assume the class defines a list of required keys
        required_keys = getattr(cls, "REQUIRED_KEYS", [])
        missing = [key for key in required_keys if key not in data]
        if missing:
            raise IRValidatorException(f"Missing required keys in YAML file: {', '.join(missing)}")

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Ensure spec and args are available
    if not hasattr(self, 'spec') or not isinstance(self.spec, dict):
        return
    if not hasattr(self, 'args') or not isinstance(self.args, dict):
        self.args = {}

    for name, spec in self.spec.items():
        # Skip if already set
        if name in self.args and self.args[name] is not None:
            continue

        # 1. Use default from spec if present
        if 'default' in spec:
            self.args[name] = spec['default']
            continue

        # 2. Try environment variable if specified
        env_var = spec.get('env')
        if env_var:
            try:
                import os
                val = os.getenv(env_var)
                if val is not None:
                    self.args[name] = val
                    continue
            except Exception:
                pass

        # 3. If spec has a callable default, call it
        if callable(spec.get('default_factory')):
            try:
                self.args[name] = spec['default_factory']()
                continue
            except Exception:
                pass

        # 4. Leave unset if no default found
        self.args[name] = None

    return self.args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements (or None if no replacement).
    # This should be defined on the instance; if not present, assume no deprecations.
    deprecated_map = getattr(self, 'deprecated_args', {})

    # Helper to format warning messages
    def _warn(arg, source):
        replacement = deprecated_map.get(arg)
        if replacement:
            msg = f"Argument '{arg}' in {source} is deprecated. Use '{replacement}' instead."
        else:
            msg = f"Argument '{arg}' in {source} is deprecated and has no replacement."
        print(msg)

    # Check CLI arguments
    for arg in cli_args:
        if arg in deprecated_map:
            _warn(arg, "CLI")

    # Check answer file arguments
    for arg in answer_file_args:
        if arg in deprecated_map:
            _warn(arg, "answer file")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not command_name or not argument_name:
        return None
    command = getattr(self, 'commands', {}).get(command_name)
    if command is None:
        return None
    return getattr(command, 'options', {}).get(argument_name)

def get_silent_args(self, args):
    """
    Return a list of argument names that are considered "silent".
    An argument is considered silent if its value is None, an empty string,
    or an empty collection (list, tuple, set, dict).
    """
    silent = []
    # Support both dict-like and iterable of (key, value) pairs
    if hasattr(args, "items"):
        iterable = args.items()
    else:
        iterable = args
    for key, value in iterable:
        if value is None:
            silent.append(key)
        elif isinstance(value, str) and value.strip() == "":
            silent.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            silent.append(key)
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if args is None:
        args = {}
    missing = [name for name in getattr(self, "required_args", []) if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        # Extract option name
        if isinstance(opt, dict):
            name = opt.get('name') or opt.get('arg_name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None) or getattr(opt, 'arg_name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or not cond:
            continue

        try:
            # If condition is callable, call it with command_name and args
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
            else:
                # Treat condition as a string expression
                # Provide a safe namespace
                namespace = {'command_name': command_name, 'args': args}
                if eval(cond, {}, namespace):
                    required.append(name)
        except Exception:
            # Ignore any errors in condition evaluation
            continue

    return required

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions; fallback to empty dict if not present
    arg_defs = getattr(self, 'arguments', {})
    for name, value in args.items():
        arg_def = arg_defs.get(name)
        if not arg_def:
            continue
        choices = arg_def.get('choices')
        if choices is None:
            continue

        # Handle arguments that accept multiple values
        if arg_def.get('multiple'):
            if not isinstance(value, (list, tuple)):
                raise ValueError(
                    f"Argument '{name}' expects multiple values, got {type(value).__name__}"
                )
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {v}. "
                        f"Expected one of {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value}. "
                    f"Expected one of {choices}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a dict or an iterable of values.
    """
    # Retrieve min and max bounds from the instance, if defined
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    # If bounds are not set, nothing to validate
    if min_val is None or max_val is None:
        return

    # Helper to raise a consistent error
    def _raise_error(name, value):
        raise ValueError(
            f"Argument '{name}' with value {value} is out of bounds "
            f"[{min_val}, {max_val}]."
        )

    # If args is a mapping, iterate over key/value pairs
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None:
                continue
            if not (min_val <= value <= max_val):
                _raise_error(key, value)
    else:
        # Assume args is an iterable of values (list, tuple, etc.)
        for idx, value in enumerate(args):
            if value is None:
                continue
            if not (min_val <= value <= max_val):
                _raise_error(idx, value)

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Default parsing parameters
    delimiter = spec_option.get('delimiter', ',')
    element_type = spec_option.get('element_type', str)
    allow_empty = spec_option.get('allow_empty', False)

    def _raise(msg):
        raise ValueError(f"Option '{option_name}' for subcommand '{subcommand}': {msg}")

    def _parse_list(value):
        if not value:
            if allow_empty:
                return []
            _raise("value cannot be empty")
        parts = value.split(delimiter)
        try:
            return [element_type(part.strip()) for part in parts]
        except Exception as exc:
            _raise(f"failed to parse list element: {exc}")

    def _parse_tuple(value):
        if not value:
            if allow_empty:
                return ()
            _raise("value cannot be empty")
        parts = value.split(delimiter)
        try:
            return tuple(element_type(part.strip()) for part in parts)
        except Exception as exc:
            _raise(f"failed to parse tuple element: {exc}")

    def _parse_dict(value):
        if not value:
            if allow_empty:
                return {}
            _raise("value cannot be empty")
        items = value.split(delimiter)
        result = {}
        for item in items:
            if '=' not in item:
                _raise(f"invalid dict item '{item}' (expected key=value)")
            key, val = item.split('=', 1)
            try:
                result[key.strip()] = element_type(val.strip())
            except Exception as exc:
                _raise(f"failed to parse dict value for key '{key}': {exc}")
        return result

    def _parse_set(value):
        if not value:
            if allow_empty:
                return set()
            _raise("value cannot be empty")
        parts = value.split(delimiter)
        try:
            return {element_type(part.strip()) for part in parts}
        except Exception as exc:
            _raise(f"failed to parse set element: {exc}")

    # Map type names to parser functions
    parsers = {
        'list': _parse_list,
        'tuple': _parse_tuple,
        'dict': _parse_dict,
        'set': _parse_set,
    }

    parser = parsers.get(type_name.lower())
    if parser is None:
        # Fallback: try to cast directly
        def _parse_default(value):
            if not value and not allow_empty:
                _raise("value cannot be empty")
            try:
                return element_type(value)
            except Exception as exc:
                _raise(f"failed to cast value: {exc}")
        return _parse_default

    return parser

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Build the base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity if requested
    if verbose:
        # Ansible uses -v, -vv, -vvv, -vvvv for increasing verbosity
        cmd.append("-" + "v" * verbose)

    # Add extra variables if provided
    if extra_vars:
        import json
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            flag = "--" + key.replace("_", "-")
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([flag, str(v)])
            else:
                cmd.extend([flag, str(value)])

    # Log the command for debugging purposes
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(f"Running ansible-playbook: {' '.join(cmd)}")
    else:
        print(f"Running ansible-playbook: {' '.join(cmd)}")

    # Execute the command
    import subprocess
    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
    )

    # Raise an error if the command failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}"
        )

    # Return the command's stdout
    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    By default all the values are strings.
    """
    # Parser specific type mapping (extend as needed)
    parser_type_map = {
        'virsh': {'memory': int, 'cpu': int},
        'ospd': {'port': int, 'debug': bool},
        'main': {'timeout': int, 'verbose': bool},
    }

    def _convert_value(val):
        """Attempt to convert a string value to int, float, bool, None, or list."""
        if not isinstance(val, str):
            return val
        s = val.strip()
        # None
        if s.lower() == 'none':
            return None
        # Boolean
        if s.lower() in ('true', 'false'):
            return s.lower() == 'true'
        # Integer
        if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
            return int(s)
        # Float
        try:
            f = float(s)
            # Ensure it's actually a float representation
            if '.' in s or 'e' in s.lower():
                return f
        except ValueError:
            pass
        # List (comma separated)
        if ',' in s:
            parts = [p.strip() for p in s.split(',')]
            return [_convert_value(p) for p in parts]
        # Default: keep as string
        return s

    for key, val in list(values_dict.items()):
        # Parser specific conversion
        if parser_name in parser_type_map and key in parser_type_map[parser_name]:
            target_type = parser_type_map[parser_name][key]
            try:
                values_dict[key] = target_type(val)
            except Exception:
                # Fallback to generic conversion if cast fails
                values_dict[key] = _convert_value(val)
        else:
            # Generic conversion
            values_dict[key] = _convert_value(val)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine spec file path
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if not spec_path:
        return {}

    # Load spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                spec = json.load(f)
            else:
                # Try YAML
                try:
                    import yaml
                    spec = yaml.safe_load(f)
                except Exception:
                    # Fallback: treat as JSON
                    f.seek(0)
                    spec = json.load(f)
    except Exception:
        return {}

    # Flatten dictionary
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if isinstance(spec, dict):
        return _flatten(spec)
    return {}

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("root cannot be empty")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    # Handle the case where root is the filesystem root
    if norm_root == os.sep:
        if norm_path == os.sep:
            return ''
        if norm_path.startswith(os.sep):
            return norm_path[1:]
    # Ensure root ends with a separator for proper prefix matching
    if not norm_root.endswith(os.sep):
        norm_root += os.sep
    if not norm_path.startswith(norm_root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped = norm_path[len(norm_root):]
    return stripped if stripped else ''
